        }
        catch (java.lang.IllegalAccessException x) {
            return bug(defn, "Native class " + str + " cannot be accessed.", x);
        }
        catch (java.lang.ClassCastException x) {
            return bug(defn, "Native class " + str + " is not a NativeApp.", x);
